package com.example.policia;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.StringTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.ItemLike;

// Libro escrito que se entrega al asignarse un oficio, con las habilidades
// y teclas de ese oficio.
public class PoliciaBook {
    static final String[] ALBANIL = new String[]{"OFICIO ALBAÑIL\n\nB: activar o desactivar el modo albañil.\nJ: usar la habilidad elegida.\nK: cambiar de habilidad.\n\nLas habilidades se desbloquean en el árbol de habilidades (clic en el icono) y cuestan XP.", "PASIVAS\n(con el modo albañil activo, se tienen al tener el oficio)\n\nManos de obra: picas piedra, ladrillos, tierra, arena y grava un 20% más rápido.\n\nAhorro de materiales: 10% de no gastar el bloque que colocas.", "Andamio seguro: sin daño por caídas de hasta 6 bloques.\n\nOjo de minero: ves todas las menas a 3 bloques, aunque no tengas ayudantes.", "1. PICO (J)\n\nTe da un pico de diamante durante 7 s con Fuerza I, Prisa minera I y Fortuna II.\nNo se puede soltar ni guardar en cofres; se puede encantar y conserva los encantamientos.\nEnfriamiento: 8 s.", "2. MURO (J)\n\nPared de 3 x 3 frente a ti. Hasta 3 muros seguidos (J de nuevo). Duran 15 s. Enfriamiento: 5 s.\n\nMejora a REFUGIO: casa con puerta, cama y cofre durante 35 s. Enfriamiento: 40 s.", "3. AYUDANTE (J)\n\nNivel I: 1 ayudante con pico de piedra. Nivel II: 3 con hierro. Nivel III: 4 con diamante.\nDuran 60 s. Enfriamiento: 30 s.\nMientras están activos ves menas cercanas (radio 4).", "Teclas de los ayudantes:\n\nH: cambiar la orden (seguir, picar delante de mi, buscar minerales).\nX (mantener): elegir el área; rueda = largo, Mayús + rueda = ancho.\nY / N: aceptar o rechazar su aviso de mineral.\nU: ver lo que llevan.", "4. LINTERNA (J o G)\n\nUna luz que sigue tu mirada hasta 48 bloques durante 60 s.\nEnfriamiento: 20 s.\n\nCosto de desbloqueo: 10 XP (AYUDANTE II 15 XP, AYUDANTE III 20 XP).", "5. TRACTOR (J)\n\nPala cargadora amarilla con cabina. Dura 45 s. Enfriamiento: 35 s. Desbloqueo: 15 XP.\nJ: invocar / bajar / volver a subir.\nMayús + J: retirarlo.\nClic derecho: montar.", "Conduciendo el tractor:\n\nW / S: avanzar y retroceder.\nA / D: girar.\nESPACIO: sube la pala. CTRL: la baja.\nG: luces.\nU: su inventario.\nMayús: bajarte.\n\nRompe lo natural que tiene delante, pero nunca construcciones de jugadores.", "PLANO DE ALBAÑIL\n(lo vende el Capataz)\n\nClic derecho en dos esquinas opuestas de tu construcción: la copia (max. 32 por lado, 2048 bloques).\nClic derecho en el suelo: tus ayudantes la construyen ahí, mirando hacia donde mires.", "Usan los bloques de tu inventario y de la bolsa de los ayudantes. Si falta algo, esperan.\nMás ayudantes = más rápido.\n\nMayús + clic al aire: cancelar la obra o borrar el plano.", "EVENTOS ALEATORIOS\n\nCada 10 a 20 minutos con el modo activo puede pasar algo:\n\nDerrumbe: aparece una pila de escombros cerca. Despejala en 3 min.\n\nSi lo resolvés ganas XP y esmeraldas.", "PEDIDOS DE ALDEANOS\n\nAgachate y clic derecho a un aldeano: te ofrece 3 trabajos (casa con puerta, corral, torre, huerta, muralla o luces).\nConstruí a menos de 32 bloques de él en 20 minutos y volvé a hablarle para cobrar.", "PLANOS YA HECHOS\n\nEl Capataz vende planos listos: Casa pequeña, Torre de vigilancia, Granja y Puente.\nSe usan igual que tu plano: clic derecho en el suelo y tus ayudantes la construyen alejándose de vos."};
    static final String[] POLICIA = new String[]{"OFICIO POLICÍA\n\nB: activar o desactivar el modo policía.\nJ: usar la habilidad elegida.\nK: cambiar de habilidad.\n\nLas habilidades se desbloquean en el árbol de habilidades (clic en el icono) y cuestan XP.", "PASIVAS\n(con el modo policía activo, se tienen al tener el oficio)\n\nChaleco reglamentario: -15% de daño de flechas y proyectiles.", "Autoridad: Héroe de la aldea I (mejores precios) y los saqueadores que te ven se asustan un momento.\n\nRecompensa: +2 XP de oficio por cada monstruo que matas cerca de una aldea.", "1. ESCUDO BALÍSTICO (J)\n\nTe protege durante unos segundos y luego entra en enfriamiento.\n\n2. REFUERZO (J)\n\nLlama a policías que luchan a tu lado. Tecla R: cambia la orden (proteger / atacar a quien te ataco / dividirse y atacar). Se mejora hasta el nivel 4 con XP.", "3. TANQUE (J)\n\nApunta y haz clic derecho para disparar un proyectil explosivo.\n\n4. TANQUE MÓVIL\n\nPilotable: W/A/S/D para moverte, clic derecho para disparar (3 disparos). Mayús: bajarte. J: volver a subir.", "5. HELICÓPTERO (J)\n\nW / S: avanzar. A / D: desplazarte.\nESPACIO: subir. CTRL: bajar.\nG: modo linterna.\nMayús: salir.", "6. ESPOSAS\n7. PERRO K9\n8. SIRENA Y TORRETA\n9. DRON DE VIGILANCIA\n\nElige la habilidad con K y usala con J. Cada una se desbloquea en el árbol de habilidades.", "COMISARIO Y MISIONES\n\nEn cada aldea hay un comisario junto a la campana. Clic derecho: tablero con 3 misiones (se renuevan cada día). Solo atiende a policías.\n\nMisiones: atrapar fugitivo, patrulla de 3 puntos, rescate, limpiar campamento, evidencia, escolta y bombas. Cada 3 cumplidas se desbloquea cazar al jefe de banda.", "ENEMIGOS\n\nLadrón, evadido y contrabandista huyen: esposalos. Pandilleros con garrote y arco, líderes, jefe de banda con barra de vida y francotiradores de torre (usa el escudo balístico). Saboteadores dejan bombas: rompe el bloque de TNT para desactivarlo. Recompensas: XP, esmeraldas y objetos especiales.", "MISIÓN ESPECIAL\n\nTras cazar al primer jefe de banda, el tablero ofrece El cerebro de la organización: dos pistas y una guarida con el jefe final, que se teletransporta e invoca refuerzos.\n\nPremio: ESCUDO DE BURBUJA (J). Esfera azul de 14 bloques que te sigue 23 s: todo lo de adentro va muy lento menos tu. Enfriamiento 26 s.", "EVENTOS ALEATORIOS\n\nCada 10 a 20 minutos con el modo activo puede pasar algo:\n\nPersecución: aparece un ladrón fugitivo que brilla. Atrapalo o eliminalo en 3 min.\n\nSi lo resolvés ganas XP y esmeraldas.", "RASTREO DE LADRONES\n\nCon el modo policía activo, si un jugador ladrón tiene estrellas de búsqueda ves arriba hacia dónde está y a cuántos bloques, más o menos.\n\n1 estrella: ±120 bloques. 2: ±80. 3: ±45. 4: ±20. 5: ubicación exacta y además brilla."};
    static final String[] LADRON = new String[]{"OFICIO LADRÓN\n\nTe transformas con la tecla B (modo ladrón). Se elige en la ventana de oficios al entrar al mundo por primera vez.\n\nTodo se hace con el modo activo.", "PASIVAS\n(con el modo ladrón activo, se tienen al tener el oficio)\n\nPies livianos: agachado, los monstruos te detectan a un cuarto de la distancia.\n\nBolsillos profundos: al morir conservas 3 objetos al azar.", "Mano rápida: con cada carterismo exitoso, 30% de llevarte una esmeralda extra.\n\nHuida: si quedas con 3 corazones o menos, corres más rápido 5 s (una vez cada 60 s).", "1. CARTERISMO\n\nAgachate (Mayús) detrás de un jugador o mob y haz clic derecho. Se tira un dado: 6 = se abren sus bolsillos (lo que llevaría al morir), 5 = tirás de nuevo, 1 a 4 = te descubren.", "2. SUERTE (trébol)\n\nInclina el dado del carterismo: cada nivel da +7% de que un 1-4 se convierta en 6 (nivel 4 = 28%). Cada nivel reemplaza al anterior. Se mejora con XP en la rama de habilidades.", "3. SILBIDO (J)\n\nLos mobs a 12 bloques miran para otro lado 7 s y quedan lentos: así te acercas por la espalda. Enfriamiento: 15 s. Desbloqueo: 10 XP.", "GOLPES GRANDES\n(menú de misiones del Jefe de ladrones)\n\nAsalto a la bóveda: aparece una bóveda llena en el 2.o sótano del casino. Al abrirla suena la alarma y llegan agentes: escapa a 120 bloques en 3 min.", "Golpe al Perista: robale los bolsillos (por detrás). Da la alarma: escapa a 100 bloques en 2:30.\n\nSi escapas cobras XP y esmeraldas extra. Si morís o se acaba el tiempo, fallas. Un golpe por día.", "EVENTOS ALEATORIOS\n\nCada 10 a 20 minutos con el modo activo puede pasar algo:\n\nOportunidad de robo: pasa un mercader adinerado que brilla. Robale los bolsillos en 3 min.\n\nSi lo resolvés ganas XP y esmeraldas.", "EL PERISTA Y LA POLICÍA\n\nCada día el Perista paga más por 3 tipos de objetos raros (x2, x2 y x3). Lo ves en el reloj de su ventana.\n\nCon estrellas de búsqueda los policías ven tu zona aproximada: con más estrellas, más precisa. Con 5 brillás."};
    static final String[] HERRERO = new String[]{"OFICIO HERRERO LEGENDARIO\n\nB: activar o desactivar el modo herrero.\nJ: usar la habilidad elegida.\nK: cambiar de habilidad.\nO: abrir el Analizador del Forjador.\n\nLas habilidades se desbloquean solas a medida que ganas XP: no hace falta árbol ni costo para elegirlas, solo alcanzar el XP necesario.", "SERVICIO Y JEFE\n\nServicio: otros jugadores se agachan y te hacen clic derecho con un objeto en la mano para pagarte esmeraldas por repararlo o mejorarlo.\n\nTu jefe es el Maestro herrero, en las herrerias: vende materiales de forja y ahí podés renunciar.", "PASIVAS\n(con el modo herrero activo, se tienen al tener el oficio)\n\nPiel de hierro: +2 de armadura y -30% de daño por fuego.\n\nManos de forja: los hornos y altos hornos a 6 bloques funden al doble de rápido.", "Durabilidad: tus herramientas y armadura se gastan un 25% menos.\n\nOjo de herrero: las menas de hierro y oro a veces sueltan pepitas o un lingote extra.", "1. GRITO DEL FORJADOR (J)\n\nGrito de área: una onda sonora sale de vos hasta 6 bloques; los enemigos dentro sueltan lo que tienen en la mano y retroceden asustados, debilitados unos segundos. Disponible desde el principio. Enfriamiento: 25 s.", "2. YUNQUE PORTÁTIL (J)\n\nSacas un yunque de la espalda, lo alzas con una mano y lo plantas en el piso. Mientras estes cerca (8 bloques): Fuerza y Héroe de la aldea. Los monstruos cerca del yunque quedan con Lentitud I y, si los matas, sueltan el doble de experiencia (y ganas el doble de XP de oficio). Al terminar los 40 s el yunque desaparece. Desbloqueo: 15 XP. Enfriamiento: 45 s (empieza al terminar).", "3. MARCA DEL HERRERO (J)\n\nMarca al enemigo que mires (brilla y queda visible) y reduce su armadura durante 15 s, haciendo que reciba más daño de cualquiera. Desbloqueo: 25 XP. Enfriamiento: 20 s.", "4. FORJA INTERIOR (J)\n\nFunde 1 lingote de hierro de tu inventario y te cura 2 corazones al instante. Sin lingote no se activa. Desbloqueo: 35 XP. Enfriamiento: 8 s.", "5. FARO DE FORJA (J)\n\nEnciende una fogata de forja: cura y da inmunidad al fuego a quien este cerca durante 60 s. Desbloqueo: 45 XP. Enfriamiento: 50 s.", "6. VÍNCULO DE ACERO (J)\n\nTe vinculas con el jugador más cercano por 30 s: una cadena translúcida los conecta, y si uno recibe daño el otro se cura una parte. Desbloqueo: 55 XP. Enfriamiento: 60 s (empieza al terminar).", "7. REPARACIÓN MAESTRA (J)\n\nSacas el yunque de la espalda, lo plantas y golpeas con el martillo como forjando: repara por completo cualquier objeto gastado que tengas en la mano (herramientas, armas, armadura, escudo, arco, elitros...), le quita el costo acumulado de yunque y deja como nuevo un yunque astillado. No gasta XP. Desbloqueo: 70 XP. Enfriamiento: 60 s (empieza al terminar).", "8. YUNQUE GUARDIÁN (J)\n\nPlantas un yunque que intercepta flechas y proyectiles cercanos, destruyéndolos con chispas y un golpe de escudo. Al terminar los 40 s el yunque desaparece. Desbloqueo: 85 XP. Enfriamiento: 45 s.", "9. ANALIZADOR DEL FORJADOR (pasiva, tecla O)\n\nSiempre activa al llegar a 35 XP. Sostené cualquier item 2 s en la mano secundaria para aprender su receta (aviso dorado en el centro de pantalla). Con O abrís una ventana con todos los items de cualquier mod: elegí uno y abajo ves su receta y el botón Craftear. Los que no tenés a mano se aprenden con el botón Pedir misión (21 misiones distintas: minar, cazar, talar, pescar, comerciar, fundir, explorar alturas y más; en verde mientras está en curso). Las recetas son aleatorias: Otra receta la cambia y Confirmar la deja fija para siempre.", "EVENTOS ALEATORIOS\n\nCada 10 a 20 minutos con el modo activo puede pasar algo:\n\nPedido urgente: la guardia necesita armas o armaduras de hierro. Tenelas en el inventario antes de 5 min.\n\nSi lo resolvés ganas XP y esmeraldas.", "ENCARGOS DE OTROS JEFES\n\nEl Jefe de policía, el Capataz y el Jefe de ladrones te encargan armas, armaduras o herramientas (botón de abajo en su menú).\nUn encargo por jefe y por día: entregalo y cobrás esmeraldas y XP."};

    static void pages(ItemStack b, String[] pg) {
        ListTag pages = new ListTag();
        for (String s : pg) {
            pages.add(StringTag.valueOf(Component.Serializer.toJson(Component.literal(s))));
        }
        b.getOrCreateTag().put("pages", (Tag) pages);
    }

    // Actualiza en silencio el libro del oficio que el jugador ya tiene.
    static void refresh(ServerPlayer p) {
        String job = PoliciaMod.job(p);
        String[] pg = "albanil".equals(job) ? ALBANIL : ("policia".equals(job) ? POLICIA : ("ladron".equals(job) ? LADRON : ("herrero".equals(job) ? HERRERO : null)));
        if (pg == null) {
            return;
        }
        for (int i = 0; i < p.getInventory().getContainerSize(); ++i) {
            ItemStack s = p.getInventory().getItem(i);
            if (s.hasTag() && job.equals(s.getTag().getString("pol_book"))) {
                PoliciaBook.pages(s, pg);
            }
        }
    }

    static void give(ServerPlayer p, String job) {
        String[] pg = "albanil".equals(job) ? ALBANIL : ("policia".equals(job) ? POLICIA : ("ladron".equals(job) ? LADRON : ("herrero".equals(job) ? HERRERO : null)));
        if (pg == null) {
            return;
        }
        for (int i = 0; i < p.getInventory().getContainerSize(); ++i) {
            ItemStack s = p.getInventory().getItem(i);
            if (!s.hasTag() || !job.equals(s.getTag().getString("pol_book"))) continue;
            PoliciaBook.pages(s, pg);
            return;
        }
        ItemStack b = new ItemStack((ItemLike) Items.WRITTEN_BOOK);
        CompoundTag t = b.getOrCreateTag();
        t.putString("title", "albanil".equals(job) ? "Guía del Albañil" : ("ladron".equals(job) ? "Guía del Ladrón" : ("herrero".equals(job) ? "Guía del Herrero Legendario" : "Guía del Policía")));
        t.putString("author", "Oficios");
        t.putString("pol_book", job);
        PoliciaBook.pages(b, pg);
        if (!p.getInventory().add(b)) {
            p.drop(b, false);
        }
        PoliciaMod.msg(p, "Recibiste un libro con las habilidades y teclas de tu oficio");
    }
}
